PROCEDURE proc_77(who:PERSON)
$v0 = FIND_EMAIL WHERE SELF.RECIPIENT={who}
$v1 = UPDATE $v0 RECIPIENT={Xena}
RETURN $v1
END

PROCEDURE move_visit_and_parent(visit:VISIT, place:PLACE)
$v0 = FIND_LAST VISIT
UPDATE $v0 WHERE SELF.PLACE={place}
$v1 = FIND_EVENT WHERE SELF.VISIT={visit}
UPDATE $v1 WHERE SELF.PLACE={place}
RETURN $v0
END

PROCEDURE proc_22(when:TIME)
$v0 = FIND_CALL WHERE SELF.TIME={when}
$v1 = FIND_PERSON WHERE SELF.ID={v0.RECIPIENT}
RETURN $v1
END
